validator:
function validate(input) {
  const [{ Views = [] }] = input;
  for (const [article, author, viewer, date] of Views) {
    if (article === null || author === null || viewer === null || date === null) return 'Every column of Views is required.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `view_date ${date} is not YYYY-MM-DD.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const dates = ['2019-07-21', '2019-07-22', '2019-08-01', '2019-08-02'];
  const Views = [];
  const articles = size === 'small' ? 1 + pick(5) : 400;
  const people = size === 'small' ? 5 : 300;
  // Each article keeps one author, as on a real site.
  const authorOf = [];
  for (let a = 1; a <= articles; a++) authorOf[a] = 1 + pick(size === 'small' ? 4 : 200);
  const rows = size === 'small' ? pick(9) : 2000;
  for (let i = 0; i < rows; i++) {
    if (Views.length && rand() < 0.12) { Views.push([...Views[pick(Views.length)]]); continue; }
    const article = 1 + pick(articles);
    const author = authorOf[article];
    const viewer = rand() < (size === 'small' ? 0.3 : 0.08) ? author : 1 + pick(people);
    Views.push([article, author, viewer, dates[pick(dates.length)]]);
  }
  return [{ Views }];
}
